INSERT INTO analyses (id, submission_id, enrichment_id, company_id, swot, pestel, porter, okrs, synthesis, tam_sam_som, benchmarking, blue_ocean, growth_hacking, scenarios, bsc, decision_matrix, status, error_message, processing_time_ms, is_visible_to_user, is_blurred, is_public, access_code, access_code_created_at, pdf_url, pdf_generated_at, approved_at, approved_by, sent_at, sent_to, created_at, updated_at, completed_at, deleted_at)
VALUES ('8d1d9998-844f-4938-a0c9-6aee6112797e', NULL, NULL, NULL, '{"summary": "Marca wellness premium enxuta, com boa tração, que precisa provar uso eficiente dos R$2M em cenário de juros altos e forte concorrência.", "threats": [{"source": "análise de mercado", "content": "SELIC 14,90% encarece capital e eleva exigência de retorno dos investidores", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Natura, Boticário, Granado e DNVBs aumentam rivalidade no nicho premium", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Marcas próprias e importados asiáticos pressionam preços e margens", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Novas regras ANVISA e logística reversa aumentam custo regulatório", "confidence": "Alta"}], "strengths": [{"source": "fato", "content": "Histórico bootstrapped prova disciplina e alta eficiência no uso de capital", "confidence": "Alta"}, {"source": "fato", "content": "Atuação B2B/B2C diversifica receita e reduz risco de canal único", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Posicionamento wellness premium com identidade brasileira reforça a marca", "confidence": "Média"}, {"source": "fato", "content": "Receita anual R$1,5–2M indica tração para captar rodada de R$2M", "confidence": "Alta"}], "weaknesses": [{"source": "fato", "content": "Escala e equipe enxutas limitam crescimento frente a grandes players", "confidence": "Alta"}, {"source": "fato", "content": "Dependência da captação de R$2M para viabilizar o plano de expansão", "confidence": "Alta"}, {"source": "fato", "content": "Plano detalhado de alocação dos R$2M ainda em definição para o pitch", "confidence": "Alta"}, {"source": "estimativa", "content": "Uso limitado de dados e IA reduz personalização e eficiência de marketing", "confidence": "Média"}], "opportunities": [{"source": "análise de mercado", "content": "Crescimento de 7–9% em HPPC wellness apoia tese de escala disciplinada", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Omnichannel integrado pode elevar LTV unindo e‑commerce, varejo e B2B", "confidence": "Média"}, {"source": "análise de mercado", "content": "Parcerias com hotéis e spas premium aceleram receita recorrente B2B", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Clean beauty e sustentabilidade permitem prêmio de preço e diferenciação", "confidence": "Média"}]}'::jsonb, '{"legal": ["Registro ANVISA e BPF elevam barreira de entrada, protegendo nicho wellness premium", "RDC ANVISA sobre alérgenos demanda revisão rigorosa de rótulos e comunicação B2B/B2C", "Regulação mais estrita de termos ''natural/orgânico'' pode exigir ajustes de claims e selos"], "social": ["Consumo seletivo: clientes buscam custo-benefício ou experiências premium bem justificadas", "Desemprego 5.60 % sustenta renda, mas sensibilidade a preço exige linhas em faixas de valor", "Tendência wellness/clean beauty favorece proposta de bem-estar e brasilidade da Santapele"], "summary": "Juros altos (SELIC 14.90%), consumo seletivo e regulação mais rígida em rotulagem/logística criam barreiras, mas abrem espaço para uma tese de wellness premium, omnichannel e eficiente em capital na rodada de R$2M.", "economic": ["SELIC 14.90% a.a. torna dívida cara; rodada de R$2M deve priorizar equity e alta eficiência", "PIB 12m 3.20 % vs gdp_growth 2.20 % e inflação 0.09% (12 meses) indicam ciclo de desaceleração", "Comércio -0.30 % e serviços 0.60 % reforçam foco em experiências de wellness e ticket médio alto"], "political": ["Reforma Tributária do consumo pode reclassificar impostos, afetando preços de cosméticos premium", "Governança fiscal em PIB 12m 3.20 % reduz espaço para incentivos; tese deve focar eficiência", "Maior escrutínio ANVISA em rotulagem exige alinhamento prévio antes de lançar novas linhas"], "environmental": ["Lei de logística reversa força revisão de embalagens e parcerias para coleta/reciclagem", "Pressão por sustentabilidade favorece ingredientes naturais e cadeias rastreáveis", "Alta de diesel eleva custos logísticos; otimizar frete e hubs reduz pegada e despesas"], "technological": ["Adoção média-alta de e-commerce/CRM exige estratégia omnichannel integrada B2B e B2C", "Personalização via IA abre espaço para rotinas e kits customizados em canais digitais", "DNVBs e concorrentes investem em influência, pressionando construção de marca digital"]}'::jsonb, '{"summary": "O nicho de cosméticos wellness no Brasil combina crescimento de 7-9% e ticket premium com alta rivalidade, substitutos fortes e juros de 14.90% a.a. Os R$2M devem priorizar marca, dados/IA leve, inovação sustentável e parcerias B2B estratégicas, estruturando o funil RACE e a eficiência operacional para escalar com disciplina e credenciar Santapele para uma próxima rodada de capital.", "buyer_power": "Poder do comprador alto: consumidor seletivo busca custo-benefício; IPCA 0.09% (acum. 12 meses) e desemprego 5.6% limitam gasto; hotéis/spas negociam forte, exigindo proposta de valor clara e diferenciação premium.", "supplier_power": "Poder do fornecedor médio-alto: dependência de petróleo e óleos essenciais e frete caro elevam custos; cadeia estável porém com logística cara e SELIC 14.90% a.a., exigindo contratos longos e diversificação de insumos.", "disruption_ai_data": "Disrupção por IA/dados média: tendência de personalização via IA e CRM avançado exige investir em dados próprios, testes A/B e automação RACE para retenção e upsell, antes que DNVBs data-driven capturem o cliente.", "threat_substitutes": "Substitutos altos: private labels de varejistas, importados asiáticos baratos e experiências de bem-estar não cosméticas disputam o orçamento; adoção digital média-alta facilita comparação e troca de marca no segmento premium.", "competitive_rivalry": "Rivalidade alta: mercado HPPC cresce 7-9% mas é concentrado em Natura/Boticário, com Granado e DNVBs expandindo lojas e M&A; Santapele precisa focar nicho wellness e experiência para defender margens.", "threat_new_entrants": "Ameaça de entrantes média: barreiras ANVISA/BPF e capital de giro caro com SELIC 14.90% a.a. filtram aventureiros, mas DNVBs digitais entram rápido via e-commerce, forçando inovação contínua e fortalecimento de marca.", "buyer_power_intensity": "Alta", "overall_attractiveness": "Média", "strategic_implications": ["Alocar ~40% dos R$2M em branding, influência e mídia performance para nicho wellness (Reach/Act), diferenciando-se de Natura/Granado e sustentando preço premium em cenário de rivalidade alta.", "Investir ~25% em CRM, dados próprios e automação (Act/Convert/Engage) para personalização baseada em IA simples, aumento de LTV e redução do poder de barganha de consumidores e redes hoteleiras.", "Destinar ~20% à inovação de portfólio clean beauty com certificações e embalagens sustentáveis, elevando barreiras a entrantes e defesa contra private labels e importados asiáticos substitutos.", "Aplicar ~15% em eficiência operacional: renegociação logística, diversificação de insumos e capital de giro, mitigando pressão de custos e impacto da SELIC 14.90% a.a., preparando métricas para próxima rodada."], "supplier_power_intensity": "Média", "disruption_ai_data_intensity": "Média", "threat_substitutes_intensity": "Alta", "competitive_rivalry_intensity": "Alta", "power_partnerships_ecosystems": "Parcerias têm poder alto: alianças com hotelaria/spas, marketplaces e certificadoras sustentáveis ampliam alcance; consolidação via M&A abre opção futura de venda ou licenciamento se Santapele consolidar o nicho wellness.", "threat_new_entrants_intensity": "Média", "power_partnerships_ecosystems_intensity": "Alta"}'::jsonb, '{"summary": "90 dias para definir alocação dos R$2M, organizar base omnichannel e iniciar pilotos B2B2C em hotelaria e spas, com foco em eficiência e dados.", "plan_90_days": [{"focus": "Fundação", "month": "Mês 1", "objective": "Preparar base estratégica e operacional do ecossistema wellness premium", "investment": "R$ 10-20 mil", "key_results": ["Concluir plano detalhado de alocação dos R$2M (Resp: founders/CFO)", "Mapear SKUs por margem e cortar SKUs irrelevantes (Resp: operações)", "Desenhar arquitetura inicial da plataforma B2B2C (Resp: produto/tech)"], "aligned_recommendation": "Eficiência operacional, margem e resiliência de caixa"}, {"focus": "Crescimento", "month": "Mês 2", "objective": "Estruturar proposta omnichannel e jornada B2B2C para hotelaria, spas e B2C", "investment": "R$ 20-40 mil", "key_results": ["Definir proposta de valor B2B por segmento e kits piloto (Resp: comercial)", "Especificar melhorias críticas de e-commerce e CRM (Resp: marketing/tech)", "Criar guideline de marca wellness premium e canais foco (Resp: branding)"], "aligned_recommendation": "Plano de crescimento Omnichannel wellness premium (tese central da rodada)"}, {"focus": "Consolidação", "month": "Mês 3", "objective": "Iniciar pilotos B2B em hotelaria/spas e governança financeira por canal", "investment": "R$ 30-50 mil", "key_results": ["Lançar 1 piloto em hotel e 1 em spa com contratos básicos (Resp: comercial)", "Implantar CRM simples com captura de dados B2B2C (Resp: marketing/tech)", "Criar rotina mensal de P&L por canal e reporte a investidores (Resp: finanças)"], "aligned_recommendation": "Expansão estruturada do canal B2B em hotelaria, spas e corporativo"}], "success_metrics": ["Plano de investimento dos R$2M validado para uso em pitch com investidores", "Pelo menos 2 pilotos B2B2C estruturados e em andamento (hotelaria/spa)", "Governança básica de dados de clientes e P&L por canal implementada"], "execution_phases": {"scale": {"focus": "Expansão controlada", "duration": "Meses 7-12", "objectives": ["Escalar modelo B2B em redes selecionadas de hotelaria e spas", "Acelerar canal digital B2C integrado à plataforma de experiências"], "key_results": ["Expandir pilotos aprovados para 5-10 clientes B2B ativos com contratos vigentes", "Integrar CRM e e-commerce em visão única de cliente B2B2C operacional"], "prerequisites": ["Validação bem-sucedida de pilotos com margens e NPS mínimos definidos", "Time-chave para canais B2B e digital estruturado e treinado"], "investment_range": "R$ 600-950 mil"}, "foundation": {"focus": "Estruturação", "duration": "Meses 1-3", "objectives": ["Clarificar tese de ecossistema wellness premium e uso dos R$2M", "Organizar operação, portfólio e dados para suportar pilotos B2B2C"], "key_results": ["Plano de alocação dos R$2M aprovado internamente e pronto para investidores", "Mapeamento de SKUs, margens e P&L por canal implementado em rotina mensal"], "investment_range": "R$ 150-250 mil", "capacity_requirements": {"team": "4-6 pessoas núcleo (fundadores, marketing, operações, finanças)", "dependencies": ["Definição interna da tese de investimento a ser apresentada na captação", "Disponibilidade de parceiros-piloto em hotelaria e spas dispostos a testar"], "skills_needed": ["Planejamento financeiro e controle de caixa", "Branding e marketing digital omnichannel", "Vendas B2B para hotelaria e spas", "Gestão de produto digital e CRM"]}}, "validation": {"focus": "Pilotos", "duration": "Meses 4-6", "objectives": ["Validar proposta B2B2C com pilotos limitados em hotelaria e spas", "Testar jornada omnichannel B2C com foco em experiência e dados"], "key_results": ["Executar 2-3 pilotos B2B com coleta estruturada de NPS e ticket por hóspede", "Implantar 1-2 experimentos de assinatura/recorrência no canal digital"], "prerequisites": ["Fase 1 concluída com plano de alocação dos R$2M definido", "Contratos-padrão B2B e políticas de dados revisados juridicamente"], "investment_range": "R$ 250-400 mil"}}, "total_investment": "R$ 60-110 mil (soma dos 3 meses)", "capacity_assessment": {"blockers": ["Escala e equipe enxutas limitam execução simultânea de muitas frentes", "Plano detalhado de alocação dos R$2M ainda em definição para o pitch"], "team_readiness": "Média", "budget_adequacy": "Suficiente", "stakeholder_alignment": "Parcial"}}'::jsonb, '{"roadmap": ["Curto Prazo (3-6 meses): Definir alocação dos R$ 2M, fechar 3-5 pilotos B2B (hotéis/spas), organizar base omnichannel e estruturar CRM com dados unificados.", "Médio Prazo (6-12 meses): Escalar pilotos validados, lançar assinatura B2C, otimizar CAC/LTV, cortar SKUs de baixa margem e atingir break-even operacional.", "Longo Prazo (12-24 meses): Provar tese de escala com receita recorrente >30%, preparar métricas para Series A (R$ 5-10M) e expandir geograficamente."], "key_findings": ["Modelo B2B2C (hotelaria + e-commerce premium) eleva LTV e reduz CAC vs. varejo tradicional.", "Assinaturas e white label para spas criam receita recorrente e previsibilidade para próxima rodada.", "Foco em dados e IA leve permite personalização sem queimar caixa em mídia de massa."], "main_findings": ["Força: Marca wellness consolidada desde 2013, operação enxuta e bootstrapped com dualidade B2B/B2C que reduz risco de concentração.", "Fraqueza: Escala limitada frente a gigantes (Natura, Granado), dependência de capital externo para crescimento e necessidade de validar eficiência do investimento.", "Oportunidade: Mercado de cosméticos wellness cresce 7-9% a.a., com espaço para plataforma B2B2C diferenciada em hotelaria premium e personalização via dados.", "Ameaça: Juros de 14.90% a.a., consumo seletivo, regulação ANVISA mais rígida e concorrência de marcas próprias e importados asiáticos."], "important_notes": ["Juros altos exigem disciplina de caixa: fatiar investimento em tranches vinculadas a milestones.", "Validar pilotos B2B (hotéis/spas) antes de escalar marketing B2C para otimizar CAC.", "Regulação ANVISA sobre rotulagem ''natural/orgânico'' pode exigir ajustes de comunicação."], "central_challenge": "Definir a alocação estratégica de R$ 2M captados para provar tese de wellness premium escalável, estruturar modelo B2B2C recorrente e credenciar Santapele para próxima rodada em cenário de juros altos e consumo seletivo.", "executive_summary": "Santapele deve usar os R$ 2M para sair da competição por preço e prateleira, posicionando-se como ecossistema de bem-estar brasileiro para hotelaria, spas e consumidores premium. Priorizar aquisição qualificada via B2B (hotéis/spas), monetização recorrente (assinaturas) e eficiência operacional com dados. Em 18-24 meses, validar unit economics e escala para Series A.", "strategic_priorities": ["Estruturar funil B2B com 3-5 redes hoteleiras/spas piloto em 90 dias.", "Lançar modelo de assinatura B2C com ticket médio superior a R$ 150/mês.", "Implementar CRM e analytics para provar unit economics e LTV/CAC à próxima rodada."], "consistency_validation": {"flags": ["Equipe de 1-10 pessoas pode limitar velocidade de execução; considerar contratações-chave em vendas B2B e dados.", "Cenário de juros altos exige reserva de caixa de 6+ meses antes de acelerar investimentos."], "legal_alignment": true, "capacity_alignment": true, "financial_alignment": true, "overall_realism_score": 7}, "overall_recommendation": "Investir os R$ 2M em tranches condicionadas a milestones, priorizando canais B2B de alto LTV (hotelaria/spas), monetização recorrente e eficiência de dados. Evitar queima de caixa em mídia de massa. Em 18-24 meses, Santapele deve provar unit economics sólidos para captar Series A de R$ 5-10M e consolidar liderança no nicho wellness premium brasileiro."}'::jsonb, '{"sam": "R$ 300M - 800M", "som": "R$ 24M - 96M", "tam": "R$ 130B - 160B", "cagr": "+8% a.a. (baseado em: growth_rate HPPC 7-9% macro_context)", "summary": "Mercado HPPC brasileiro grande; nicho wellness premium permite projetar SOM de ~R$ 24-96M/ano no cenário realista.", "assumptions": ["TAM HPPC Brasil ~R$130-160B (fonte: ABIHPEC/Euromonitor, 2023)", "SAM=0,25-0,5% do TAM p/ wellness premium B2B/B2C foco Sudeste", "SOM 3-20% do SAM p/ PME nichada com execução em 5-10 anos"], "som_scenarios": {"realistic": {"probability": 50, "value_range": "R$ 24M - 96M", "market_share": "8-12% do SAM"}, "optimistic": {"probability": 20, "value_range": "R$ 45M - 160M", "market_share": "15-20% do SAM"}, "conservative": {"probability": 30, "value_range": "R$ 9M - 40M", "market_share": "3-5% do SAM"}}, "tam_scenarios": {"realistic": {"probability": 50, "value_range": "R$ 130B - 160B"}, "optimistic": {"probability": 20, "value_range": "R$ 150B - 190B"}, "conservative": {"probability": 30, "value_range": "R$ 115B - 140B"}}, "confidence_level": 70, "calculation_notes": "TAM usa dados HPPC Brasil; SAM 0,25-0,5% nicho wellness; SOM aplica 3-20% do SAM por cenário.", "data_sources_used": {"direct_data": ["Estimativas de tamanho do mercado de Cosméticos e HPPC Brasil (ABIHPEC/Euromonitor)", "Macro_context industry_trends: setor HPPC, crescimento CAGR 7-9% Brasil"], "proxy_calculations": ["SAM estimado como 0,25-0,5% do TAM p/ nicho wellness premium B2B hotelaria/spas e B2C", "SOM calculado como % do SAM conforme faixas de market share p/ PME estabelecida"], "benchmark_extrapolations": ["Ajuste de CAGR setorial para +8% a.a. com base em faixa 7-9% HPPC", "Validação de faixas de receita SOM vs. baliza PME R$ 5-50M/ano"]}, "estimation_method": "dados_diretos", "baseline_recommendation": "conservative"}'::jsonb, '{"summary": "Benchmark com Granado, Avatim, Natura &Co e L''Occitane au Brésil indica Santapele forte em wellness, porém com menor escala, mídia e distribuição que líderes de HPPC. Mercado HPPC brasileiro grande; nicho wellness premium permite projetar SOM de ~R$ 24-96M/ano no cenário realista.", "best_practices": ["Portfólio wellness premium com identidade brasileira clara, similar a Avatim e L''Occitane.", "Modelo híbrido B2B/B2C que espelha estratégias omnichannel dos líderes de HPPC.", "Marca nichada em bem-estar e experiência sensorial, alinhada à tendência clean beauty."], "performance_gaps": ["Menor reconhecimento de marca nacional frente a Natura, Granado e L''Occitane.", "Escala de distribuição e sortimento menores, limitando presença em canais de massa.", "Menor investimento em mídia e influência digital que grandes DNVBs de beleza."], "competitors_analyzed": ["Granado Pharmácias", "Avatim", "Natura &Co", "L''Occitane au Brésil"]}'::jsonb, '{"raise": ["Elevar padrão de experiência sensorial em hotéis, spas e retreats parceiros", "Aumentar transparência radical sobre origem, impacto e rastreabilidade", "Intensificar personalização de rotinas de autocuidado via dados e IA leve"], "create": ["Criar plataforma white label de bem-estar para hotelaria e spas de luxo", "Lançar assinaturas B2C baseadas em rituais completos de wellness brasileiro", "Desenvolver laboratório co-criado com terapeutas e spas para novas linhas"], "reduce": ["Reduzir presença em multimarcas que não reforçam posicionamento premium", "Enxugar verba em influenciadores de massa pouco alinhados ao wellness", "Diminuir dependência de vendas pontuais e oportunísticas sem recorrência"], "summary": "Santapele sai da disputa por prateleira e desconto e se posiciona como ecossistema de bem-estar brasileiro para hotelaria, spas e consumidores premium. O foco do investimento é criar uma plataforma B2B2C de experiências e dados (assinaturas, co-criação com spas, white label para hotelaria), elevando radicalmente a experiência sensorial e a personalização, com transparência socioambiental, enquanto corta SKUs irrelevantes, mídia de massa e canais que não reforcem o posicionamento wellness premium.", "eliminate": ["Eliminar descontos agressivos típicos do varejo de cosméticos", "Cortar SKUs sem narrativa clara de bem-estar e baixa margem", "Abandonar campanhas de beleza genérica sem foco em wellness"], "new_value_curve": "Migrar de marca de cosméticos premium para plataforma de ecossistema wellness B2B2C."}'::jsonb, '{"summary": "Usar R$2M para tracionar aquisição qualificada via hotéis/spas e e-commerce e estruturar monetização recorrente que eleve LTV e prove escala.", "leap_loop": {"name": "LEAP Loop", "type": "aquisição", "steps": ["Land: Atrair B2C via mídia paga e conteúdo wellness; B2B via prospecção e parcerias com hotéis e spas premium", "Engage: Nutrir leads com conteúdo sensorial da marca, amostras em hotéis/spas e fluxos de e-mail personalizados", "Activate: Converter em compras com bundles de teste, kits de amenities e ofertas de primeira compra no e-commerce", "Propagate: Estimular indicações via programa em hotéis/spas, gift cards e recompensas por reviews e social share"], "metrics": ["CAC total", "CAC por canal (B2B hotelaria/spas vs B2C e-commerce)", "Leads qualificados/mês", "Taxa de ativação (lead → 1ª compra)", "Custo por lead (CPL) em mídia paga", "Coeficiente viral B2C", "Payback de CAC (meses)"], "bottleneck": "Baixa maturidade em dados/IA e equipe enxuta limitam segmentação, testes e otimização de CAC nos canais-chave"}, "scale_loop": {"name": "SCALE Loop", "type": "monetização", "steps": ["Satisfy: Garantir experiência premium consistente B2B/B2C com SLAs claros, QA rigoroso e suporte próximo a hotéis/spas", "Convert: Estruturar planos B2B recorrentes e packs B2C de assinatura/recarga com descontos por valor e prazo", "Loop Back: Criar CRM único omnichannel, com cadência de recompra, reativação e upsell baseado em dados de uso", "Expand: Aumentar ticket com linhas exclusivas p/ hotéis, kits presente e cross-sell de rotinas completas"], "metrics": ["LTV B2C", "LTV B2B (hotelaria/spas)", "Taxa de recompra em 60/90 dias", "% de receita recorrente (planos, assinaturas, contratos)", "Receita de upsell/cross-sell por cliente", "Ticket médio por segmento (B2B/B2C)", "Margem bruta e contribuição por canal"], "bottleneck": "Ausência de CRM e ofertas recorrentes bem estruturadas reduz LTV, previsibilidade de receita e alavancagem do investimento de R$2M"}}'::jsonb, '{"realist": {"name": "Cenário Realista", "description": "Crescimento moderado: PIB 2,20%, serviços 0,60% e desemprego em 5,60%. SELIC em 14,90% a.a. e inflação em 0,09%/12m mantêm consumo seletivo e pressão por margens. Comércio segue perto de -0,30%. Os R$ 2M financiam eficiência operacional, fortalecimento digital e teste disciplinado da tese wellness premium, com foco em sustentabilidade de caixa.", "probability": 60, "required_actions": ["Fatiar o investimento de R$ 2M em marcos trimestrais ligados a LTV/CAC, churn e margem de contribuição.", "Otimizar mix de produtos e canais, priorizando linhas de maior margem e giro rápido no B2B e B2C.", "Negociar contratos logísticos e de insumos para reduzir impacto do câmbio em R$ 5,35/USD e do diesel.", "Construir playbook de vendas B2B para hotelaria e spas, com processos replicáveis e previsibilidade de receita."]}, "summary": "Os principais riscos estão em juros altos, consumo seletivo, câmbio e regulação sanitária/logística. Com um plano de investimento fatiado, foco em margens altas, caixa robusto e diversificação B2B/B2C, a Santapele pode usar os R$ 2M para validar a tese wellness premium e chegar preparada à próxima rodada, mesmo sob cenários macro adversos.", "optimistic": {"name": "Cenário Otimista", "description": "Ambiente melhora: PIB em 3,20%/12m consolida alta, comércio reage ao -0,30% e confiança sobe mesmo com SELIC ainda em 14,90% a.a. Câmbio perto de R$ 5,35/USD mantém custos sob controle. Wellness premium cresce; Santapele usa os R$ 2M para escalar omnichannel e B2B em hotéis/spas, preparando nova rodada em 18–24 meses.", "probability": 20, "required_actions": ["Destinar parte dos R$ 2M para acelerar e-commerce e CRM omnichannel, integrando B2B e B2C com foco em clientes de alta renda.", "Expandir portfólio wellness premium com lançamentos alinhados a tendências de clean beauty e sustentabilidade.", "Fechar contratos âncora com redes hoteleiras e spas, priorizando ticket médio alto e margens brutas superiores a 65%."]}, "pessimistic": {"name": "Cenário Pessimista", "description": "Choque negativo: aperto fiscal, confiança em queda e comércio aprofunda o -0,30%, enquanto indústria segue em -0,40%. SELIC permanece em 14,90% a.a. com crédito restrito; câmbio supera o patamar de R$ 5,35/USD, elevando logística e insumos. Reguladores endurecem rotulagem e logística, atrasando lançamentos. Os R$ 2M viram colchão de sobrevivência, não de aceleração.", "probability": 20, "required_actions": ["Reduzir CAPEX e congelar expansões físicas, mantendo caixa para 18–24 meses mesmo com vendas abaixo do plano.", "Reforçar relacionamento com clientes B2B estratégicos, oferecendo condições flexíveis em troca de contratos de longo prazo.", "Simplificar portfólio, cortando SKUs de baixa margem e alta complexidade regulatória junto à ANVISA."]}, "mitigation_tactics": ["Desenhar plano de investimento em fases, com cortes automáticos se indicadores de venda, margem ou caixa ficarem abaixo de gatilhos predefinidos.", "Manter estrutura enxuta e terceirização flexível de produção e logística para ajustar custos rapidamente.", "Diversificar canais e tickets: combinar kits premium de alto valor com opções de entrada para mitigar consumo seletivo.", "Fortalecer governança de dados e indicadores (LTV, CAC, cohort B2B/B2C) para sustentar a próxima rodada pós-R$ 2M."], "early_warning_signals": ["Alta ou queda abrupta da SELIC em relação aos 14,90% atuais, sinalizando mudança no custo de capital e no apetite de investidores.", "Persistência de retração no comércio abaixo de -0,30% e piora do PIB abaixo de 2,20%, indicando enfraquecimento relevante da demanda.", "Desvalorização do real além da referência de R$ 5,35/USD e novas normas da ANVISA em rotulagem/logística que aumentem custos de conformidade."]}'::jsonb, '{"summary": "BSC foca receita recorrente, experiência premium e plataforma B2B2C para sustentar o plano de captação de R$ 2M.", "customer": ["Alcançar NPS >= 70 entre hotéis, spas e consumidores premium", "Ter 40 parceiros ativos na plataforma (hotéis/spas) em 24 meses"], "financial": ["Aumentar receita recorrente B2B2C em 60% em 24 meses", "Elevar margem bruta para 55% reduzindo SKUs e descontos"], "learning_growth": ["Capacitar time em dados, CRM e CX (100% do time-chave)", "Criar célula de inovação com testes mensais de experiências"], "internal_processes": ["Lançar plataforma B2B2C com MVP em até 9 meses", "Reduzir em 30% o tempo de lançamento de novos produtos"]}'::jsonb, '{"score": "8.4/10", "summary": "A matriz multicriterial considera ROI, risco e tempo de maturação. A1 foi priorizada por combinar crescimento de receita, fortalecimento da tese wellness premium e preservação de caixa em cenário de juros altos, consumo seletivo e câmbio volátil. A2 entra como segundo vetor, explorando o diferencial da Santapele em hotelaria/spas, porém com maior complexidade contratual e de responsabilidade civil, o que justifica parecer jurídico prévio e contratos-padrão robustos. A3 reforça a resiliência da operação, melhorando margem e reduzindo vulnerabilidade a choques de custo (câmbio, insumos, logística). O ciclo de revisão trimestral, com gatilhos extraordinários regulatórios e de compliance, permite ajustar o plano rapidamente diante de mudanças da ANVISA, da Reforma Tributária ou de decisões judiciais que afetem o modelo. Próximos passos: (1) detalhar alocação dos R$ 2M por iniciativa dentro das três recomendações, com cronograma e metas quantitativas; (2) elaborar contratos e políticas críticas com apoio jurídico (especialmente B2B e LGPD); (3) implantar o painel de métricas sugerido para reportar aos investidores o avanço da tese e preparar a próxima rodada de captação.", "criteria": ["Retorno sobre o investimento em 3-5 anos (ROI)", "Risco financeiro, operacional e regulatório", "Tempo para captura de resultados e preparo para próxima rodada"], "alternatives": ["A1 - Crescimento balanceado Omnichannel (B2B+B2C) com foco em margem e caixa", "A2 - Aceleração B2B em hotelaria/spas e canais corporativos", "A3 - Verticalização produtiva e expansão física agressiva"], "review_cycle": {"frequency": "Trimestral", "extraordinary_triggers": ["Mudança regulatória >10% custo", "Bloqueio de licenciamento", "Decisão judicial relevante", "Falha de compliance LGPD/setorial", "Entrada de competidor relevante"]}, "score_comparison": "+18% acima da segunda opção", "monitoring_metrics": ["Receita mensal por canal (B2B vs B2C)", "Margem bruta consolidada (%) e por linha de produto", "CAC, LTV e payback de marketing (meses) por canal digital", "Giro de estoque (dias) e nível de ruptura nos principais SKUs", "Ticket médio e taxa de recompra (B2C e B2B)", "NPS/satisfação em clientes finais e parceiros (hotéis, spas, corporativos)"], "recommended_option": "A1 - Crescimento balanceado Omnichannel (B2B+B2C) com foco em margem e caixa", "final_recommendation": "A melhor opção é a A1 - Crescimento balanceado Omnichannel (B2B+B2C) com foco em margem e caixa, usando os R$ 2M para acelerar marca, canais digitais e B2B, preservando liquidez em cenário de SELIC 14.90% a.a. e preparando a próxima rodada em 18-24 meses.", "priority_recommendations": [{"title": "Plano de crescimento Omnichannel wellness premium (tese central da rodada)", "budget": "R$800k-1,0M", "priority": 1, "timeline": "18-24 meses", "description": "Alocar a maior parte dos R$ 2M em fortalecimento de marca wellness premium, aceleração de B2C digital e integração com canais físicos/parceiros, preservando caixa. Ações: reforço de branding, mídia de performance, CRM/loyalty, melhoria de UX do e-commerce, testes de loja conceito/pop-up em praças estratégicas e parceria com pontos de experiência (spas, clínicas, hotéis âncora). Complexidade institucional baixa: decisões tomadas pelos sócios atuais, sem necessidade de assembleias formais além das já previstas no contrato social.", "legal_feasibility": {"risk_level": "Baixo", "mitigation_plan": "1) Manter revisão anual de termos de uso, política de privacidade e políticas de troca/devolução com advogado especializado em varejo e LGPD; 2) Implementar rotina de compliance para aprovar peças de marketing sensíveis (claims de saúde/bem-estar) antes da veiculação; 3) Formalizar contratos-padrão simples com parceiros físicos, limitando responsabilidade civil e definindo claramente uso de marca.", "requires_legal_opinion": false, "regulatory_dependencies": ["Conformidade contínua com RDC ANVISA sobre rotulagem e registro de cosméticos", "Adequação à Lei de Logística Reversa para embalagens", "Conformidade LGPD em CRM, e-commerce e campanhas de marketing", "Respeito ao Código de Defesa do Consumidor (CDC) em vendas B2C"], "requires_statutory_change": false}}, {"title": "Expansão estruturada do canal B2B em hotelaria, spas e corporativo", "budget": "R$400-600k", "priority": 2, "timeline": "12-18 meses", "description": "Usar parte dos recursos para fortalecer o canal B2B em hotelaria/spas e contas corporativas (amenities, gifts corporativos, programas de bem-estar). Ações: desenho de propostas de valor por segmento, desenvolvimento de kits e embalagens B2B, equipe/comercial dedicado, playbook de implantação em redes, e SLAs de atendimento/logística. Complexidade institucional média: exige negociação com múltiplas partes (redes hoteleiras, spas, empresas) e estruturação de contratos, mas sem necessidade de alteração estatutária.", "legal_feasibility": {"risk_level": "Médio", "mitigation_plan": "1) Obter parecer jurídico antes de padronizar contratos B2B, assegurando limites claros de responsabilidade civil, política de devolução e garantias; 2) Criar contratos-modulares (hotelaria, spas, corporativo) com cláusulas de compliance sanitário e de marca; 3) Exigir dos parceiros comprovação de conformidade sanitária local para armazenamento/exposição; 4) Avaliar contratação/adequação de seguro de responsabilidade civil para produtos; 5) Como alternativa de menor risco para clientes menores, priorizar inicialmente contratos simplificados (pedido + condições gerais) e pilotos de curto prazo antes de contratos de longo prazo.", "requires_legal_opinion": true, "regulatory_dependencies": ["Contratos comerciais B2B com cláusulas de responsabilidade, SLA e garantias", "Conformidade com legislação consumerista (CDC) para produtos disponibilizados a hóspedes/colaboradores", "Adequação às normas de vigilância sanitária locais em hotéis/spas (uso, armazenamento e exposição de cosméticos)", "Seguro de responsabilidade civil para eventuais reações adversas em uso intensivo"], "requires_statutory_change": false}}, {"title": "Eficiência operacional, margem e resiliência de caixa", "budget": "R$200-300k", "priority": 3, "timeline": "6-12 meses", "description": "Direcionar o restante do capital para aumentar margem e reduzir riscos de juros altos e câmbio. Ações: otimização de cadeia de suprimentos, renegociação com fornecedores, melhoria de planejamento de compras/estoque, avaliação de terceiristas com melhor relação custo/qualidade, revisão de embalagens (custos x percepção premium) e implantação de rotinas de orçamento/forecast. Complexidade institucional baixa: ajustes internos e contratuais padrão, sem assembleias extraordinárias.", "legal_feasibility": {"risk_level": "Baixo", "mitigation_plan": "1) Incluir cláusulas de compliance ANVISA, BPF e logística reversa nos contratos com fornecedores/terceiristas; 2) Realizar auditorias periódicas (documentais e, quando possível, in loco) em parceiros críticos; 3) Submeter mudanças relevantes de embalagem/rotulagem a análise técnica regulatória antes da implementação; 4) Manter acompanhamento tributário básico em função da Reforma Tributária sobre consumo.", "requires_legal_opinion": false, "regulatory_dependencies": ["Manutenção de Boas Práticas de Fabricação (BPF) junto a terceiros", "Conformidade com novas normas da ANVISA para rotulagem e alérgenos", "Adequação à legislação trabalhista e de terceirização em logística e produção", "Cumprimento contínuo da Lei de Logística Reversa nas mudanças de embalagem"], "requires_statutory_change": false}}]}'::jsonb, 'completed', NULL, 199758, false, false, false, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-02 02:35:56.068195+00'::timestamptz, '2025-12-02 02:39:15.711352+00'::timestamptz, '2025-12-02 02:39:15.564064+00'::timestamptz, NULL)
