INSERT INTO analyses (id, submission_id, enrichment_id, company_id, swot, pestel, porter, okrs, synthesis, tam_sam_som, benchmarking, blue_ocean, growth_hacking, scenarios, bsc, decision_matrix, status, error_message, processing_time_ms, is_visible_to_user, is_blurred, is_public, access_code, access_code_created_at, pdf_url, pdf_generated_at, approved_at, approved_by, sent_at, sent_to, created_at, updated_at, completed_at, deleted_at)
VALUES ('30f07565-ced1-401d-8695-731fb3f70481', NULL, NULL, NULL, '{"summary": "", "threats": null, "strengths": null, "weaknesses": null, "opportunities": null}'::jsonb, '{"legal": ["RDC ANVISA de rotulagem impõe ajustes rápidos em claims e design antes de escalar", "Regras de logística reversa ampliam custo B2C, pedindo parcerias em reciclagem", "Nova regulação da biodiversidade pode limitar ou encarecer insumos naturais brasileiros"], "social": ["Consumo de luxo/experiência resiliente ante varejo geral -0,30% favorece proposta wellness", "Alta adesão a clean beauty eleva prêmio por marca eco-luxury com origem em hospitalidade", "Busca por jornada phygital reforça sinergia SPA Emiliano + e-commerce Santapele"], "summary": "Juros altos e câmbio pressionam custos, mas luxo wellness segue resiliente. Com incentivos verdes e tendências clean beauty/phygital, há janela para captar R$2M e escalar SPAs, e-commerce e amenities com forte disciplina regulatória.", "economic": ["SELIC 14,90% encarece dívida e torna equity de R$2M mais raro, pressionando valuation", "PIB +3,2% e serviços +0,6% sustentam demanda por SPAs e amenities de luxo", "Câmbio USD/BRL 5,34 encarece embalagens plásticas e importados, exigindo hedge de custos"], "political": ["Reforma tributária 2025 traz incerteza sobre carga para varejo premium de HPPC", "Foco fiscal do governo pode elevar tributos sobre luxo, afetando margem de eco-luxury", "Incentivos à economia verde abrem espaço para captar com tese ESG bem estruturada"], "environmental": ["Incentivos à economia verde favorecem linhas com menor impacto e embalagens sustentáveis", "Volatilidade do petróleo afeta custo de plástico, acelerando migração para refis e vidro", "Futuro rigor contra greenwashing exige métricas auditáveis de sustentabilidade"], "technological": ["Adoção tech média no setor abre flanco para Santapele liderar CRM e dados first-party", "CAC digital em alta exige foco em retenção, CRM e canais B2B para reduzir payback", "Novas D2C com influenciadores elevam barra de conteúdo e storytelling digital"]}'::jsonb, '{"summary": "Eco-luxury wellness é nicho atraente, mas rivalidade alta, CAC crescente e volatilidade de custos exigem alavancar R$ 2M em dados, ecossistemas de hotelaria/SPAs e foco em nichos premium para escalar com disciplina.", "buyer_power": "Poder do comprador médio: varejo -0,30% força promoções, mas luxo é resiliente; IPCA 0,09% e desemprego 5,6% mantêm demanda A/B estável, enquanto hotéis de luxo concentram volume e barganha.", "supplier_power": "Poder de fornecedores médio-alto: câmbio a 5,34 e petróleo/plástico voláteis elevam custos de embalagens e frete; insumos naturais estáveis mitigam, mas comprimem margens em linhas de maior volume.", "disruption_ai_data": "Disrupção de IA/dados em aceleração: grandes grupos otimizam CRM, mídia e pricing com algoritmos, elevando CAC; Santapele precisa usar dados de e-commerce e SPAs para segmentação e LTV.", "threat_substitutes": "Substitutos relevantes: outras rotinas wellness (SPAs concorrentes, aromaterapia, marcas D2C) disputam o mesmo ticket; CAC digital em alta reduz espaço para erros em portfólio e posicionamento.", "competitive_rivalry": "Alta rivalidade: concentração em Natura/Boticário, M&A ativos e entrada de marcas internacionais de clean beauty elevam pressão; exige narrativa ESG superior e experiência SPA phygital proprietária.", "threat_new_entrants": "Ameaça de entrantes média: barreiras ANVISA, logística reversa e rigor em claims verdes elevam custo inicial, mas D2C digital permite novas marcas nichadas com alto investimento em influenciadores.", "buyer_power_intensity": "Média", "overall_attractiveness": "Média", "strategic_implications": ["REACH: focar mídia segmentada em luxo/clean beauty e co-marketing com hotéis parceiros e SPAs franqueados para reduzir CAC frente a grandes grupos e novas marcas D2C.", "ACT: orquestrar jornadas phygital SPA+ecommerce com amostras, consultorias e conteúdos educativos para capturar leads qualificados e dados proprietários de comportamento.", "CONVERT: criar bundles exclusivos para hotelaria e canal farma premium, com políticas comerciais e contratos de longo prazo que mitiguem poder de barganha dos grandes compradores.", "ENGAGE: estruturar CRM avançado e programas de fidelidade apoiados em IA leve (recomendações, next best offer) para elevar LTV, reduzir dependência de mídia paga e proteger margens."], "supplier_power_intensity": "Média", "disruption_ai_data_intensity": "Média", "threat_substitutes_intensity": "Média", "competitive_rivalry_intensity": "Alta", "power_partnerships_ecosystems": "Ecossistemas favoráveis: expansão de SPAs e amenities de luxo e incentivos à economia verde abrem parcerias com hotelaria, redes farma premium e marketplaces ESG, acelerando alcance e prova social.", "threat_new_entrants_intensity": "Média", "power_partnerships_ecosystems_intensity": "Alta"}'::jsonb, '{"summary": ""}'::jsonb, '{"roadmap": ["Curto Prazo (3-6 meses): Estruturar operação B2B (equipe comercial, contratos hotelaria), lançar piloto de assinatura D2C e definir modelo de franquia SPA", "Médio Prazo (6-12 meses): Escalar 3-5 contratos B2B relevantes, abrir 2 franquias SPA e implementar CRM com automação de marketing", "Longo Prazo (12+ meses): Consolidar liderança em amenities eco-luxury, atingir 5+ SPAs franqueados e preparar métricas para Series A (R$ 8-15M)"], "key_findings": ["B2B recorrente (amenities hotelaria) oferece CAC menor e LTV maior que D2C, devendo ser prioridade de alocação", "Ecossistema phygital (SPA + e-commerce + assinatura) cria barreira competitiva difícil de replicar por concorrentes", "Uso faseado do capital com gates de performance preserva opcionalidade para próxima rodada (Series A)"], "main_findings": ["FORÇA: Brand equity premium associado ao Hotel Emiliano e posicionamento ESG nativo diferenciador no mercado de luxo", "FRAQUEZA: Equipe enxuta (1-10) e orçamento de marketing limitado restringem velocidade de escala e competição com grandes players", "OPORTUNIDADE: Expansão B2B em hotelaria de luxo e modelo de franquias de SPA permitem crescimento asset-light com receita recorrente", "AMEAÇA: Juros altos (SELIC 14,9%), câmbio volátil (USD 5,34) e CAC digital crescente pressionam margens e exigem disciplina financeira"], "important_notes": ["R$ 2M são insuficientes para escalar todos os canais simultaneamente - priorização é crítica", "Modelo de franquias de SPA reduz capex mas exige estrutura de suporte e padrão de qualidade", "Dependência de terceiros para produção pode limitar margens e controle de qualidade"], "central_challenge": "Alocar R$ 2M de forma estratégica para escalar um ecossistema phygital de wellness eco-luxury, equilibrando expansão de SPAs, e-commerce e amenities B2B em cenário de juros altos e CAC crescente.", "executive_summary": "Santapele possui brand equity único (Hotel Emiliano) e modelo diversificado (SPA, amenities, e-commerce), mas escala limitada e CAC alto exigem uso disciplinado dos R$ 2M. Priorizar B2B recorrente (amenities/hotelaria) para fluxo previsível, escalar SPAs via franquias e fortalecer CRM para elevar LTV. Cenário macro desafiador, mas nicho eco-luxury é resiliente.", "strategic_priorities": ["Escalar B2B amenities para hotéis de luxo no Brasil e exterior (receita recorrente)", "Expandir SPAs via franquias com modelo asset-light e padrão Emiliano", "Estruturar CRM e programa de assinatura para elevar LTV no canal D2C"], "consistency_validation": {"flags": ["Equipe atual (1-10) insuficiente para executar plano completo - necessário contratar 3-5 pessoas-chave nos primeiros 6 meses", "Modelo de franquia SPA exige estruturação jurídica e COF (Circular de Oferta de Franquia) antes de escalar", "Projeções de escala assumem manutenção de margens - pressão de câmbio em insumos pode comprometer"], "legal_alignment": true, "capacity_alignment": false, "financial_alignment": true, "overall_realism_score": 7}, "overall_recommendation": "Alocar 50% em B2B/amenities, 30% em expansão de SPAs franqueados e 20% em CRM/D2C. Usar capital de forma faseada com revisões trimestrais. Próxima rodada (Series A) deve ser buscada em 18-24 meses com faturamento de R$ 5-8M comprovado."}'::jsonb, '{"sam": "", "som": "", "tam": "", "cagr": "", "summary": "", "assumptions": null, "confidence_level": 0, "calculation_notes": "", "estimation_method": ""}'::jsonb, '{"summary": "Santapele se destaca em eco-luxo e experiência, mas precisa ampliar escala, canais e awareness frente a líderes.", "best_practices": ["Posicionamento eco-luxury com storytelling autêntico da origem em hotelaria de alto padrão", "Modelo híbrido SPA + e-commerce + amenities, oferecendo experiência phygital integrada", "Alinhamento forte com tendências clean beauty e ESG para público premium exigente"], "performance_gaps": ["Menor reconhecimento de marca nacional frente a players como Granado e L''Occitane", "Escala de produção limitada, reduzindo poder de negociação de custos e margens", "Dependência de poucos canais âncora (hotelaria Emiliano), elevando risco de concentração"], "competitors_analyzed": ["Granado/Phebo", "Aesop", "Simple Organic", "L''Occitane au Brésil"]}'::jsonb, '{"raise": ["Integração profunda com dados de hotéis, SPAs e reservas em tempo real", "Padrões de excelência sensorial alinhados a hotelaria cinco estrelas", "Investimento em P&D com ativos brasileiros de alta performance clínica"], "create": ["Plataforma de dados de bem-estar para personalizar amenities e protocolos", "Programa de assinatura SPA-at-home integrado a hotéis parceiros", "Hub de co-criação com terapeutas e hóspedes para linhas hipersegmentadas"], "reduce": ["Dependência de e-commerce próprio como único canal de escala", "Variedade de SKUs pouco rentáveis ou com baixa aderência em hotelaria", "Gastos em mídia paga sem segmentação por cluster de hóspedes e SPAs"], "summary": "Santapele migra de fabricante de cosméticos eco-luxury para orquestradora de um ecossistema de bem-estar baseado em dados de hotelaria e SPAs, com ofertas phygitais (amenities personalizados, SPA-at-home por assinatura e co-criação com terapeutas) que reduzem CAC, aumentam LTV e criam uma barreira competitiva difícil de replicar, sustentando o uso disciplinado dos R$ 2M em ativos escaláveis.", "eliminate": ["Campanhas com influenciadores caros e genéricos", "Lançamentos sazonais sem conexão com dados de uso real", "Descontos agressivos que corroem margem e diluem percepção de luxo"], "new_value_curve": "De marca de cosméticos eco-luxury para plataforma de bem-estar guiada por dados, integrada à hotelaria e ao SPA-at-home premium."}'::jsonb, '{"summary": "Usar R$2M para escalar aquisição multicanal focada em wellness premium e estruturar recorrência (assinaturas, SPA+ecom) para elevar LTV.", "leap_loop": {"name": "LEAP Loop", "type": "acquisition", "steps": ["Land: Tráfego pago, influenciadores wellness e parcerias com hotéis/SPAs para atrair leads B2C e B2B.", "Engage: Conteúdo sensorial/educativo, quiz de rotina e amostras em SPAs/hotéis para capturar e qualificar leads.", "Activate: Onboarding por WhatsApp/e-mail, kits de experimentação e ofertas de 1ª compra para reduzir fricção.", "Propagate: Programa de indicação, UGC com amenities instagramáveis e códigos de desconto para amigos."], "metrics": ["CAC total e por canal", "Taxa visita>lead e lead>1ª compra", "CTR e engajamento de conteúdo", "Coeficiente viral e % vendas via indicação"], "bottleneck": "Dependência de poucos canais premium e CAC digital alto para gerar volume de novos clientes qualificados."}, "scale_loop": {"name": "SCALE Loop", "type": "monetization", "steps": ["Satisfy: Experiência SPA+produto impecável, unboxing premium e suporte próximo para encantar e reduzir devoluções.", "Convert: Bundles de rotinas, upgrades de serviços SPA e planos corporativos para monetizar melhor cada lead.", "Loop Back: CRM segmentado, fluxo de recompra automática e clube de fidelidade integrado SPA + e-commerce.", "Expand: Cross-sell entre linhas Santapele/Santopé/casa, assinaturas e expansão de contratos B2B de amenities."], "metrics": ["LTV por segmento (B2C, SPA, B2B amenities)", "Taxa de recompra e churn de assinaturas", "NPS e avaliações de produtos/SPAs", "Receita de upsell/cross-sell por cliente"], "bottleneck": "Baixa recorrência estruturada (assinaturas/fidelidade) limita LTV mesmo com alta satisfação de experiência."}}'::jsonb, '{"realist": {"name": "Cenário Realista", "description": "SELIC permanece alta (~14,90%), IPCA contido (0,09% 12m) e USD/BRL em torno de 5,34. Serviços crescem moderadamente (+0,6%), mantendo demanda por SPAs e experiências de luxo, mas investidores preferem renda fixa. Captação de R$ 2M ocorre com diluição cuidadosa; crescimento é disciplinado, focado em nichos rentáveis e eficiência operacional.", "probability": 60, "required_actions": ["Alocar os R$ 2M em um mix: ~40% expansão comercial B2B (hotelaria, amenities), ~30% marketing digital/CRM, ~30% capital de giro e estoques críticos", "Otimizar CAC digital com foco em performance e dados de CRM, priorizando retenção e LTV em vez de pura aquisição", "Negociar contratos de longo prazo com fornecedores de insumos naturais e embalagens para reduzir impacto do câmbio a USD/BRL 5,34", "Desenhar plano de próxima rodada (Seed/Series A) ancorado em métricas: crescimento de receita 30–40% a.a. e margens por canal"]}, "summary": "O risco central está na combinação de juros muito altos, câmbio volátil e aumento de CAC em um mercado de luxo disputado. Ao usar os R$ 2M de forma faseada, proteger margens via B2B recorrente e CRM, e monitorar SELIC, câmbio e serviços, Santapele pode ajustar ritmo de expansão de SPAs, e-commerce e amenities, preservando opcionalidade para uma próxima rodada.", "optimistic": {"name": "Cenário Otimista", "description": "Até 2027, SELIC cai para ~9%, PIB mantém +3,2% a.a. e serviços seguem em alta (>+0,6%). Incentivos verdes e reforma tributária favorecem eco-luxury. USD/BRL recua abaixo de 5,0, aliviando embalagens. Luxo wellness cresce forte; Santapele capta R$ 2M com alta demanda e acelera SPAs, e-commerce e amenities premium.", "probability": 20, "required_actions": ["Direcionar >50% dos R$ 2M em expansão de SPAs/franquias ancoradas em hotéis de luxo, priorizando São Paulo e RJ", "Investir forte em branding e PR internacional para posicionar Santapele como referência brasileira em clean beauty de hotelaria", "Antecipar certificações (Vegan, Cruelty Free, ISO 22716) e claims ESG para capturar incentivos verdes e parcerias globais"]}, "pessimistic": {"name": "Cenário Pessimista", "description": "Aperto fiscal e ruído político elevam SELIC >16% e USD/BRL >6,0, encarecendo embalagens ligadas ao petróleo. Consumo desacelera, inclusive em luxo; CAC digital dispara e marcas internacionais intensificam promoções. Reforma tributária traz ônus adicional ao varejo. Captação de R$ 2M atrasa ou ocorre em termos menos favoráveis, exigindo forte enxugamento.", "probability": 20, "required_actions": ["Redimensionar plano de expansão, focando apenas SPAs e hotéis B2B de maior margem e contratos recorrentes", "Congelar projetos de alto capex e renegociar prazos com fabricantes terceirizados e franqueados para preservar caixa", "Reforçar ticket médio com kits e assinaturas home care, priorizando canais de melhor margem (e-commerce próprio e venda direta B2B)"]}, "mitigation_tactics": ["Estruturar plano de investimento modular: liberar os R$ 2M em fases atreladas a marcos de receita/margem por canal, permitindo ajuste rápido a SELIC e câmbio", "Reduzir exposição cambial via nacionalização máxima de insumos, contratos em reais e revisão periódica de portfólio de produtos intensivos em embalagem plástica", "Fortalecer canal B2B com contratos de 2–3 anos em hotelaria de luxo, garantindo previsibilidade de demanda para SPAs e amenities", "Construir base de dados própria (CRM, fidelidade) para diminuir dependência de mídia paga em cenário de CAC digital crescente"], "early_warning_signals": ["Movimento da SELIC: cortes consistentes rumo a <12% sinalizam ambiente mais otimista; alta para >16% indica cenário recessivo", "Trajetória do USD/BRL: apreciação acima de 5,8 por 3 meses pressiona embalagens e margens; queda abaixo de 5,0 abre espaço para acelerar expansão", "Tendências de serviços e luxo: desaceleração do índice de serviços (>0,6% para negativo) e retração em hotelaria/spas indicam freio na expansão física"]}'::jsonb, '{"summary": "R$2M focados em dados, recorrência e ecossistema SPA/hotelaria, reduzindo CAC e elevando LTV.", "customer": ["Alcançar NPS ≥ 70 em hóspedes, assinantes e clientes de SPA", "Dobrar base de clientes B2B ativos em hotelaria e SPAs parceiros"], "financial": ["Elevar receita recorrente para 40% do faturamento em 24 meses", "Aumentar LTV médio em 60% via SPAs, amenities e assinaturas"], "learning_growth": ["Formar 100 terapeutas parceiros em protocolos exclusivos Santapele", "Estruturar time de growth e dados, com OKRs focados em CAC/LTV"], "internal_processes": ["Implantar plataforma de dados unificada de hóspedes, SPAs e ecom", "Criar esteiras phygitais: SPA-at-home, co-criação e cross-sell B2B"]}'::jsonb, '{"score": "", "summary": "", "criteria": null, "alternatives": null, "review_cycle": {"frequency": "", "extraordinary_triggers": null}, "score_comparison": "", "monitoring_metrics": null, "recommended_option": "", "final_recommendation": "", "priority_recommendations": null}'::jsonb, 'completed', NULL, 391487, true, false, false, '6AG7B464', '2025-12-01 15:29:55.114167+00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-01 15:20:00.359256+00'::timestamptz, '2025-12-02 01:39:33.30224+00'::timestamptz, '2025-12-01 15:26:31.573909+00'::timestamptz, NULL)
